contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "depositAmount must be positive");
        require(address(this).balance >= depositAmount, "not enough balance");

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint256 balAfter = address(c).balance;

        assert(balBefore - balAfter == depositAmount);
    }

    receive() external payable {}
}

